'use strict';
Promise.all([fetch('./data.json'),fetch('./culture.json'),fetch('./particles.json'),fetch('./particle_lessons.json'),fetch('./kanji_words.json')]).then(async ([r,c,p,l,w])=>{if(!r.ok||!c.ok||!p.ok||!l.ok||!w.ok)throw Error('No se pudieron cargar los datos');cultureData=await c.json();particleBank=await p.json();particleLessons=await l.json();kanjiWords=await w.json();return r.json()}).then(d=>{data=d;render();window.__ritoStartup&&(window.__ritoStartup.loaded=true)}).catch(e=>el(`<h2>No se pudo cargar el contenido</h2><p>${esc(e.message)}</p><p>Comprueba que data.json está publicado junto a index.html.</p>`));if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
